// 婚姻账独立逐字段冷存；所有来源保留原记录，未知/重名字段不自动修复。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "family_marriage.hpp"
#include "succession_personal_assets.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
#include "family_extension_projection.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;using P=MarriageProposal;using R=MarriageReply;using D=MarriageDissolution;
// 空顺序只用于新建本账；已保存字段集合必须完整且唯一。
bool order(const FieldOrder& value,const std::set<StableId>& fields){return value.empty()||(value.size()==fields.size()&&std::set<StableId>(value.begin(),value.end())==fields);}
// 引用形状单独核验，跨事实身份、原生日和顺序由完整婚姻validator核验。
bool id(const StableId& text){return !text.empty()&&text.size()<=256;}
Status shape(const P& p){return p.kind=="family_marriage_proposed"&&p.source.intent=="offer_marriage"&&order(p.field_order,{"kind","source"})?common_success():common_failure("InvalidMarriageProposal");}
Status shape(const R& r){std::set<StableId> fields{"kind","proposal_id","actor_id","decision","tick","revision"};if(r.confirmation)fields.insert("confirmation");return r.kind=="family_marriage_replied"&&id(r.proposal_id)&&id(r.actor_id)&&(r.decision=="accepted"||r.decision=="refused"||r.decision=="withdrawn")&&bool(r.confirmation)==(r.decision=="accepted")&&r.tick>=0&&r.revision>=0&&order(r.field_order,fields)?common_success():common_failure("InvalidMarriageReply");}
Status shape(const D& d){return d.kind=="family_marriage_dissolved"&&id(d.marriage_id)&&d.source.intent=="accept_dissolution"&&order(d.field_order,{"kind","marriage_id","source"})?common_success():common_failure("InvalidMarriageDissolution");}
// 本人节点来源仍走自己的严格codec，不能在外层隐藏另一个意愿字段。
MarriageStatementSource source(const V& v){auto decoded=decode_marriage_statement_source(v);if(!decoded.ok)boundary::fail(decoded.error.original.code,"marriage/source");return std::move(decoded.value);}
P proposal(const V& v){using namespace boundary;fields(v,{"kind","source"},{},"marriage/proposal");P p;p.kind=get_string(v,"kind","");p.source=source(field(v,"source",""));p.field_order=boundary::order(v);return p;}
R reply(const V& v){using namespace boundary;fields(v,{"kind","proposal_id","actor_id","decision","tick","revision"},{"confirmation"},"marriage/reply");R r;r.kind=get_string(v,"kind","");r.proposal_id=get_string(v,"proposal_id","");r.actor_id=get_string(v,"actor_id","");r.decision=get_string(v,"decision","");r.tick=get_int(v,"tick","");r.revision=get_int(v,"revision","");if(const auto* confirmed=v.find("confirmation"))r.confirmation=source(*confirmed);r.field_order=boundary::order(v);return r;}
D dissolution(const V& v){using namespace boundary;fields(v,{"kind","marriage_id","source"},{},"marriage/dissolution");D d;d.kind=get_string(v,"kind","");d.marriage_id=get_string(v,"marriage_id","");d.source=source(field(v,"source",""));d.field_order=boundary::order(v);return d;}
V encode(const MarriageProposal& p){return family_projection::encode([&](auto& w){return emit_marriage_proposal_fields(w,p);});}
V encode(const MarriageReply& p){return family_projection::encode([&](auto& w){return emit_marriage_reply_fields(w,p);});}
V encode(const MarriageDissolution& p){return family_projection::encode([&](auto& w){return emit_marriage_dissolution_fields(w,p);});}
// 每个来源和可选同意均显式标记，不通过表长度猜测新旧语义。
Status visit(CodecVisitor& c,P& p){c.field("kind",p.kind);c.object("source",[&](CodecVisitor& at){return visit_marriage_statement_source(at,p.source);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,R& r){c.field("kind",r.kind);c.field("proposal_id",r.proposal_id);c.field("actor_id",r.actor_id);c.field("decision",r.decision);c.field("tick",r.tick);c.field("revision",r.revision);c.optional("confirmation",r.confirmation,[](CodecVisitor& at,MarriageStatementSource& source){return visit_marriage_statement_source(at,source);});common_checkpoint::strings(c,"field_order",r.field_order);if(!c.status().ok)return c.status();auto valid=shape(r);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,D& d){c.field("kind",d.kind);c.field("marriage_id",d.marriage_id);c.object("source",[&](CodecVisitor& at){return visit_marriage_statement_source(at,d.source);});common_checkpoint::strings(c,"field_order",d.field_order);if(!c.status().ok)return c.status();auto valid=shape(d);return valid.ok?c.status():c.reject(valid.error.original.code);}
// 有限新表拒重复事实号，孤立头和跨表重号再由原Common历史校验拒绝。
template<class T,class Read>void decode_table(const V& v,OrderedTable<T>& out,Read read){const auto& rows=boundary::object(v,"marriage/table");if(rows.size()>65536)boundary::fail("MarriageFactLimit","");for(const auto& row:rows){auto value=read(row.second);auto valid=shape(value);if(!valid.ok)boundary::fail(valid.error.original.code,row.first);if(!id(row.first)||!out.insert(row.first,std::move(value)))boundary::fail("InvalidMarriageFactId",row.first);}}
template<class T>V encode_table(const OrderedTable<T>& values){V::Dict out;for(const auto& row:values.rows())out.emplace_back(row.first,encode(row.second));return V{std::move(out)};}
}
Outcome<FamilyMarriageState> decode_family_marriage(const V& input){try{auto unique=validate_succession_json_unique(input);if(!unique.ok)return {false,{},unique.error};using namespace boundary;fields(input,{"proposals","replies","dissolutions"},{},"family_marriage");FamilyMarriageState out;decode_table(field(input,"proposals",""),out.proposals,proposal);decode_table(field(input,"replies",""),out.replies,reply);decode_table(field(input,"dissolutions",""),out.dissolutions,dissolution);out.field_order=boundary::order(input);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_marriage_proposal_fields(ProjectionWriter& w,const MarriageProposal& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.object("source",[&](auto& out){return emit_marriage_statement_source_fields(out,p.source);});return w.order_fields(p.field_order);}
Status emit_marriage_reply_fields(ProjectionWriter& w,const MarriageReply& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.field("proposal_id",p.proposal_id);w.field("actor_id",p.actor_id);w.field("decision",p.decision);w.field("tick",p.tick);w.field("revision",p.revision);if(p.confirmation)w.object("confirmation",[&](auto& out){return emit_marriage_statement_source_fields(out,*p.confirmation);});return w.order_fields(p.field_order);}
Status emit_marriage_dissolution_fields(ProjectionWriter& w,const MarriageDissolution& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"");w.field("kind",p.kind);w.field("marriage_id",p.marriage_id);w.object("source",[&](auto& out){return emit_marriage_statement_source_fields(out,p.source);});return w.order_fields(p.field_order);}
Status emit_family_marriage_fields(ProjectionWriter& w,const FamilyMarriageState& s){if(!order(s.field_order,{"proposals","replies","dissolutions"}))return w.reject("BoundaryFieldOrderMismatch","family_marriage");auto table=[&](std::string_view key,const auto& rows,auto emit){return w.object(key,[&](auto& out){for(const auto& row:rows.rows()){out.object(row.first,[&](auto& value){return emit(value,row.second);});if(!out.status().ok)return out.status();}return out.status();});};table("proposals",s.proposals,emit_marriage_proposal_fields);table("replies",s.replies,emit_marriage_reply_fields);table("dissolutions",s.dissolutions,emit_marriage_dissolution_fields);return w.order_fields(s.field_order);}
BoundaryValue encode_family_marriage(const FamilyMarriageState& s){return family_projection::encode([&](auto& w){return emit_family_marriage_fields(w,s);});}
Status visit_family_marriage_checkpoint(CodecVisitor& c,FamilyMarriageState& state){common_checkpoint::table(c,"proposals",state.proposals,[](CodecVisitor& at,P& p){return visit(at,p);});common_checkpoint::table(c,"replies",state.replies,[](CodecVisitor& at,R& r){return visit(at,r);});common_checkpoint::table(c,"dissolutions",state.dissolutions,[](CodecVisitor& at,D& d){return visit(at,d);});common_checkpoint::strings(c,"field_order",state.field_order);if(!c.status().ok)return c.status();return order(state.field_order,{"proposals","replies","dissolutions"})?c.status():c.reject("BoundaryFieldOrderMismatch");}
}
